from typing import List, Optional

def is_palindrome(s: str, ignore_case: bool = True, ignore_spaces: bool = True) -> bool:
    """EGRR_PATTERN: Palindrome check with configurable options."""
    if not s:
        return True

    cleaned = s
    if ignore_case:
        cleaned = cleaned.lower()
    if ignore_spaces:
        cleaned = ''.join(c for c in cleaned if c.isalnum())

    return cleaned == cleaned[::-1]

def longest_palindrome_substring(s: str) -> str:
    """EGRR_PATTERN: Longest palindromic substring using expand around center."""
    if not s:
        return ""

    if len(s) == 1:
        return s

    def expand(left: int, right: int) -> str:
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return s[left + 1:right]

    longest = s[0]

    for i in range(len(s)):
        # Odd length palindromes
        odd = expand(i, i)
        if len(odd) > len(longest):
            longest = odd

        # Even length palindromes
        if i + 1 < len(s):
            even = expand(i, i + 1)
            if len(even) > len(longest):
                longest = even

    return longest

def anagram_groups(words: List[str]) -> List[List[str]]:
    """EGRR_PATTERN: Group anagrams efficiently using sorted key."""
    if not words:
        return []

    from collections import defaultdict

    groups = defaultdict(list)
    for word in words:
        key = ''.join(sorted(word.lower()))
        groups[key].append(word)

    return list(groups.values())

def kmp_search(text: str, pattern: str) -> List[int]:
    """EGRR_PATTERN: KMP string search algorithm."""
    if not pattern:
        return list(range(len(text) + 1))
    if not text or len(pattern) > len(text):
        return []

    # Build failure function
    failure = [0] * len(pattern)
    j = 0
    for i in range(1, len(pattern)):
        while j > 0 and pattern[i] != pattern[j]:
            j = failure[j - 1]
        if pattern[i] == pattern[j]:
            j += 1
        failure[i] = j

    # Search
    matches = []
    j = 0
    for i in range(len(text)):
        while j > 0 and text[i] != pattern[j]:
            j = failure[j - 1]
        if text[i] == pattern[j]:
            j += 1
        if j == len(pattern):
            matches.append(i - len(pattern) + 1)
            j = failure[j - 1]

    return matches
